class Solution { public: int longestSubarray(vector<int>& nums,int limit){deque<int> maximum,minimum;int left=0,answer=0;for(int right=0;right<(int)nums.size();++right){while(!maximum.empty()&&nums[maximum.back()]<nums[right])maximum.pop_back();while(!minimum.empty()&&nums[minimum.back()]>nums[right])minimum.pop_back();maximum.push_back(right);minimum.push_back(right);while(nums[maximum.front()]-nums[minimum.front()]>limit){if(maximum.front()==left)maximum.pop_front();if(minimum.front()==left)minimum.pop_front();++left;}answer=max(answer,right-left+1);}return answer;} };
